1	package hotel.reports;
2	
3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	
5	import hotel.messages.EmailSender;
6	import hotel.messages.SentMessages;
7	import hotel.reservations.Guest;
8	import hotel.reservations.NewReservation;
9	import hotel.reservations.PriceCalculator;
10	import hotel.reservations.RatePlan;
11	import hotel.reservations.Reservation;
12	import hotel.reservations.ReservationService;
13	import hotel.reservations.ReservationStore;
14	import hotel.rooms.Rooms;
15	import java.time.LocalDate;
16	import java.time.YearMonth;
17	import org.junit.jupiter.api.BeforeEach;
18	import org.junit.jupiter.api.Test;
19	
20	class ReportsTest {
21	
22	    private final Rooms rooms = new Rooms();
23	    private final ReservationStore store = new ReservationStore();
24	    private final ReservationService service =
25	            new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(new SentMessages()));
26	
27	    private Reservation book(int roomNumber, String checkIn, String checkOut, RatePlan plan) {
28	        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
29	        return service.create(new NewReservation(
30	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan));
31	    }
32	
33	    @BeforeEach
34	    void someReservations() {
35	        Reservation april = book(201, "2027-04-01", "2027-04-03", RatePlan.STANDARD);
36	        Reservation lateMarch = book(101, "2027-03-30", "2027-04-02", RatePlan.NON_REFUNDABLE);
37	        Reservation suite = book(301, "2027-04-02", "2027-04-04", RatePlan.STANDARD);
38	        book(102, "2027-04-01", "2027-04-05", RatePlan.STANDARD); // never paid
39	        Reservation cancelled = book(202, "2027-04-01", "2027-04-02", RatePlan.STANDARD);
40	        service.confirm(april.id());
41	        service.confirm(lateMarch.id());
42	        service.confirm(suite.id());
43	        service.checkIn(suite.id());
44	        service.confirm(cancelled.id());
45	        service.cancel(cancelled.id());
46	    }
47	
48	    @Test
49	    void occupancyListsThePaidReservationsCoveringTheNight() {
50	        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 1));
51	
52	        assertEquals("""
53	                room,type,reservation,check_in,check_out
54	                101,STANDARD,2,2027-03-30,2027-04-02
55	                201,DELUXE,1,2027-04-01,2027-04-03
56	                total,2/5
57	                """, csv);
58	    }
59	
60	    @Test
61	    void theCheckOutNightIsNotOccupied() {
62	        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 3));
63	
64	        assertEquals("""
65	                room,type,reservation,check_in,check_out
66	                301,SUITE,3,2027-04-02,2027-04-04
67	                total,1/5
68	                """, csv);
69	    }
70	
71	    @Test
72	    void revenueSumsTheMoneyKeptFromReservationsStartingInTheMonth() {
73	        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 4));
74	
75	        // the unpaid reservation and the refunded cancellation bring nothing
76	        assertEquals("""
77	                reservation,room,check_in,check_out,status,amount
78	                1,201,2027-04-01,2027-04-03,CONFIRMED,779.80
79	                3,301,2027-04-02,2027-04-04,CHECKED_IN,1159.80
80	                total,1939.60
81	                """, csv);
82	    }
83	
84	    @Test
85	    void aCancelledNonRefundableReservationStillCountsAsRevenue() {
86	        Reservation may = book(101, "2027-05-10", "2027-05-11", RatePlan.NON_REFUNDABLE);
87	        service.confirm(may.id());
88	        service.cancel(may.id());
89	
90	        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 5));
91	
92	        assertEquals("""
93	                reservation,room,check_in,check_out,status,amount
94	                6,101,2027-05-10,2027-05-11,CANCELLED,212.42
95	                total,212.42
96	                """, csv);
97	    }
98	
99	    @Test
100	    void anEmptyMonthHasOnlyTheTotal() {
